namespace sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public List<StatusUpdate> Updates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTime Timestamp { get; set; }
}

using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Models;

namespace sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Models;
using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Services;

namespace sv_12c774fb8d9d4e729502a7b18ecdc9c8.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTime(2026, 7, 1, 17, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Austin, TX", Timestamp = new DateTime(2026, 6, 20, 9, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at sorting facility", Location = "Dallas, TX", Timestamp = new DateTime(2026, 6, 21, 3, 30, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Departed facility", Location = "Dallas, TX", Timestamp = new DateTime(2026, 6, 21, 14, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at regional hub", Location = "Memphis, TN", Timestamp = new DateTime(2026, 6, 22, 6, 15, 0, DateTimeKind.Utc) },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTime(2026, 6, 18, 12, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Portland, OR", Timestamp = new DateTime(2026, 6, 15, 10, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "In transit", Location = "Tacoma, WA", Timestamp = new DateTime(2026, 6, 16, 8, 45, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Out for delivery", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 17, 7, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Delivered — left at front door", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 17, 14, 22, 0, DateTimeKind.Utc) },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Out for Delivery",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTime(2026, 6, 24, 18, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 21, 11, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at sorting facility", Location = "Newark, NJ", Timestamp = new DateTime(2026, 6, 21, 20, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "In transit", Location = "Toledo, OH", Timestamp = new DateTime(2026, 6, 22, 16, 30, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at local facility", Location = "Chicago, IL", Timestamp = new DateTime(2026, 6, 23, 5, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Out for delivery", Location = "Chicago, IL", Timestamp = new DateTime(2026, 6, 24, 8, 0, 0, DateTimeKind.Utc) },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Models;

namespace sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Services;

public class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Models
@using sv_12c774fb8d9d4e729502a7b18ecdc9c8.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_isLoading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-primary" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Current Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@(_shipment.EstimatedDelivery?.ToString("f") ?? "N/A")</dd>
    </dl>

    @if (_shipment.Updates.Count > 0)
    {
        <h4>Tracking History</h4>
        <table class="table">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.Updates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _isLoading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && !_isLoading)
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _isLoading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, _cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation change or dispose) — nothing to show.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        _loadedTrackingNumber = null;
        await LoadShipmentAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

